<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref} from 'vue';import {invoke} from '@tauri-apps/api/core';import {desktop} from './workspace';
type Entry={title:string,url:string};type Library={enabled:boolean,items:Record<string,Entry>,conflicts:number};const library=ref<Library>({enabled:false,items:{},conflicts:0});const title=ref(''),url=ref(''),editId=ref(''),baseline=ref<Entry|null>(null),message=ref(''),busy=ref(false),confirmId=ref('');let tick:ReturnType<typeof setInterval>|undefined;
async function run(kind:string,params:Record<string,unknown>={}){if(!desktop)throw Error('请在桌面版管理本机书签');return invoke<Library>('bookmark_action',{kind,params})}
async function refresh(){if(busy.value)return;try{const state=await run('list');if(!busy.value)library.value=state}catch(e){message.value=String(e)}}
function clear(){editId.value='';title.value='';url.value='';baseline.value=null}
function edit(id:string,b:Entry){editId.value=id;baseline.value={...b};title.value=b.title;url.value=b.url;confirmId.value=''}
async function command(kind:string,params:Record<string,unknown>){if(busy.value)return;busy.value=true;try{library.value=await run(kind,params);message.value=library.value.conflicts?'书签刚被其他窗口修改，已显示最新值，请重新编辑。':'已保存';if(kind==='edit'){clear();confirmId.value=''}}catch(e){message.value=String(e)}finally{busy.value=false}}
const save=()=>command('edit',{changes:[{id:editId.value||crypto.randomUUID(),before:baseline.value,after:{title:title.value.trim()||url.value.trim(),url:url.value.trim()}}]});onMounted(()=>{refresh();tick=setInterval(refresh,3500)});onBeforeUnmount(()=>clearInterval(tick));
</script>
<template><section class="simple-panel book-panel"><div class="section-heading"><h2>共享书签 <small>{{Object.keys(library.items).length}}</small></h2><label><input type="checkbox" :checked="library.enabled" :disabled="busy||!desktop" @change="command('enable',{enabled:($event.target as HTMLInputElement).checked})"> 启用环境间同步</label></div><p class="settings-hint">开启后重开环境。新建的 HTTP(S) 书签会在其他环境的书签工具栏「星相共享书签」出现；已有私人书签不导入。编辑和删除也会同步，Cookie 和历史记录不会共享。</p><form class="book-form" @submit.prevent="save"><input v-model="title" placeholder="名称" maxlength="500" aria-label="书签名称"><input type="url" required v-model="url" placeholder="https://…" aria-label="书签网址"><button class="button primary" :disabled="busy||!desktop">{{editId?'保存修改':'添加书签'}}</button><button type="button" v-if="editId" class="text-button" @click="clear">取消</button></form><p role="status">{{message}}</p><div v-for="(b,id) in library.items" :key="id" class="book-row"><div><strong>{{b.title}}</strong><small>{{b.url}}</small></div><button class="text-button" @click="edit(String(id),b)">编辑</button><button v-if="confirmId!==id" class="text-button" @click="confirmId=String(id)">删除</button><template v-else><button class="text-button" @click="command('edit',{changes:[{id,before:b,after:null}]})">确认从所有同步环境移除</button><button class="text-button" @click="confirmId=''">取消</button></template></div><p v-if="!Object.keys(library.items).length" class="settings-hint">还没有共享书签。可以在这里添加，也可以启用同步后在浏览器里收藏网页。</p></section></template>
<style scoped>.book-panel{padding:24px}.book-panel label,.book-panel p{font-size:13px;color:#435571}.book-form,.book-row{display:flex;gap:12px;align-items:center;margin-top:16px}.book-form input{min-width:0;flex:1;padding:9px;border:1px solid #ccd4e1;border-radius:6px}.book-row{border-top:1px solid #e1e6ee;padding:12px 0}.book-row div{flex:1;min-width:0}.book-row small{display:block;overflow-wrap:anywhere;color:#4c6280}</style>
